html:
{#- UAE Tax Invoice 80mm (pos_0001, SPEC section 7). Bilingual English / Arabic. The data
    comes from pos_next.pos_0001.uae.uae_receipt(doc), the same rules as the till receipt. -#}
{%- set r = uae_receipt(doc) -%}
{%- macro bi(label, value, cls="") -%}
<div class="bi {{ cls }}"><span class="en">{{ label.en | e }}</span><span class="ar" dir="rtl" lang="ar">{{ label.ar | e }}</span><span class="val" dir="ltr">{{ value | e }}</span></div>
{%- endmacro -%}
<style>
	@page { size: 80mm auto; margin: 0; }
	.uae-receipt { width: 72mm; margin: 0 auto; padding: 2mm 0; font-family: Arial, "Noto Sans Arabic", "DejaVu Sans", Tahoma, sans-serif; font-size: 11px; line-height: 1.35; color: #000; }
	.uae-receipt .c { text-align: center; }
	.uae-receipt .b { font-weight: bold; }
	.uae-receipt .sm { font-size: 10px; }
	.uae-receipt .lg { font-size: 14px; }
	.uae-receipt .company { font-size: 15px; font-weight: bold; }
	.uae-receipt .title { font-size: 15px; font-weight: bold; margin: 6px 0; }
	.uae-receipt .logo { max-width: 60%; max-height: 30mm; }
	.uae-receipt .bi { display: flex; align-items: baseline; gap: 4px; margin: 2px 0; }
	.uae-receipt .bi .en { flex: 0 1 auto; }
	.uae-receipt .bi .ar { flex: 1 1 auto; text-align: right; }
	.uae-receipt .bi .val { flex: 0 0 auto; max-width: 55%; text-align: right; overflow-wrap: anywhere; }
	.uae-receipt .pair { display: flex; justify-content: space-between; gap: 4px; margin: 2px 0; }
	.uae-receipt .item { margin: 4px 0; }
	.uae-receipt .ar-name { text-align: right; }
	.uae-receipt hr { border: 0; margin: 5px 0; }
	.uae-receipt hr.dash { border-top: 1px dashed #000; }
	.uae-receipt hr.solid { border-top: 2px solid #000; }
</style>
<div class="uae-receipt">
	{%- if r.logo %}<div class="c"><img class="logo" src="{{ r.logo | e }}" alt=""></div>{% endif %}
	<div class="c company">{{ (r.company.name or doc.company) | e }}</div>
	{%- if r.company.address %}<div class="c sm">{{ r.company.address | e }}</div>{% endif %}
	{%- if r.company.tax_id %}{{ bi(r.labels.trn, r.company.tax_id, "sm b") }}{% endif %}
	{%- if r.company.phone %}<div class="c sm" dir="ltr">{{ r.company.phone | e }}</div>{% endif %}
	<div class="c title">{{ r.title.en }}<br><span dir="rtl" lang="ar">{{ r.title.ar }}</span></div>
	{%- if doc.docstatus == 0 %}<div class="c b">DRAFT</div>{% endif %}
	<hr class="dash">
	{{ bi(r.labels.credit_note_no if r.is_return else r.labels.invoice_no, doc.name, "sm") }}
	{%- if r.is_return and doc.return_against %}{{ bi(r.labels.original_invoice, doc.return_against, "sm") }}{% endif %}
	{{ bi(r.labels.date, frappe.utils.formatdate(doc.posting_date, "yyyy-mm-dd") ~ " " ~ r.time, "sm") }}
	{%- if doc.pos_profile %}{{ bi(r.labels.till, doc.pos_profile, "sm") }}{% endif %}
	{{ bi(r.labels.cashier, r.cashier, "sm") }}
	{%- if r.sales_persons %}{{ bi(r.labels.sales_person, r.sales_persons, "sm") }}{% endif %}
	{{ bi(r.labels.customer, doc.customer_name or doc.customer, "sm") }}
	{%- if r.customer_tax_id %}{{ bi(r.labels.customer_trn, r.customer_tax_id, "sm") }}{% endif %}
	<hr class="dash">
	{%- for line in r.lines %}
	<div class="item">
		<div class="b">{{ line.name | e }}</div>
		{%- if line.name_ar %}<div class="ar-name" dir="rtl" lang="ar">{{ line.name_ar | e }}</div>{% endif %}
		<div class="pair sm"><span dir="ltr">{{ line.qty }} {{ line.uom | e }} x {{ line.rate }}{% if line.vat %} ({{ line.vat }}){% endif %}</span><span dir="ltr">{{ line.amount }}</span></div>
	</div>
	{%- endfor %}
	<hr class="dash">
	{{ bi(r.labels.net, r.net) }}
	{%- if r.discount %}{{ bi(r.labels.discount, "-" ~ r.discount) }}{% endif %}
	{%- for tax in r.taxes %}{{ bi(tax.label, tax.amount) }}{% endfor %}
	{%- if r.rounding %}{{ bi(r.labels.rounding, r.rounding) }}{% endif %}
	<hr class="solid">
	{{ bi(r.labels.total, r.total, "lg b") }}
	{%- for p in r.payments %}
	<div class="pair"><span>{{ p.mode | e }}</span><span dir="ltr">{{ p.amount }}</span></div>
	{%- endfor %}
	{%- if r.change %}{{ bi(r.labels.change, r.change, "b") }}{% endif %}
	{%- if r.outstanding %}{{ bi(r.labels.balance_due, r.outstanding, "b") }}{% endif %}
	<hr class="dash">
	{%- if r.footer %}
	<div class="c sm">{{ r.footer | e | replace("\n", "<br>") }}</div>
	{%- else %}
	<div class="c sm">{{ r.labels.thank_you.en }}<br><span dir="rtl" lang="ar">{{ r.labels.thank_you.ar }}</span></div>
	{%- endif %}
</div>
